import type { Vec3 } from '../contracts/math';

export type ForceObstacleKind = 'teleporter' | 'fan' | 'conveyor';

/** Read only view of the ball handed to obstacle logic, so the layer stays independent from Rapier. */
export interface BallSample {
  position: Vec3;
  velocity: Vec3;
  radius?: number;
}

/** Instant relocation requested by a teleporter. */
export interface TeleportEffect {
  position: Vec3;
  velocity: Vec3;
  /** spin is dropped on a jump so the ball does not keep drifting sideways after the portal */
  clearAngularVelocity: boolean;
}

/** What a single obstacle wants to do to the ball during one physics step. */
export interface ObstacleEffect {
  obstacleId: string;
  kind: ForceObstacleKind;
  /** velocity change in m/s, already integrated over the step */
  deltaVelocity?: Vec3;
  teleport?: TeleportEffect;
}

export interface ObstacleConfigBase {
  id: string;
  kind: ForceObstacleKind;
  enabled?: boolean;
}

export interface ObstacleStepContext {
  /** fixed physics step in seconds */
  dt: number;
  /** seconds since the hole started, drives pulsing fans */
  elapsed: number;
}

export interface BallObstacle<TConfig extends ObstacleConfigBase = ObstacleConfigBase> {
  readonly id: string;
  readonly kind: ForceObstacleKind;
  readonly config: TConfig;
  enabled: boolean;
  update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null;
  reset(): void;
}
