import type { Vec3 } from '../contracts/math';
import { clamp } from '../physics/helpers';
import type { BallObstacle, BallSample, ObstacleConfigBase, ObstacleEffect, ObstacleStepContext } from './types';
import { cloneVec3, lengthVec3, normalizeVec3, scaleVec3 } from './vec';
import type { ZoneShape } from './zones';
import { zoneContains } from './zones';

export type TeleportVelocityMode = 'preserve' | 'redirect' | 'fixed';

export interface TeleporterConfig extends ObstacleConfigBase {
  kind: 'teleporter';
  /** volume that swallows the ball */
  entry: ZoneShape;
  /** where the ball reappears */
  exit: Vec3;
  /** exit facing, required by the redirect and fixed modes */
  exitDirection?: Vec3;
  velocityMode?: TeleportVelocityMode;
  /** exit speed for the fixed mode, m/s */
  exitSpeed?: number;
  /** multiplier applied to the resulting exit speed */
  speedMultiplier?: number;
  /** the ball must travel at least this fast to be swallowed, m/s */
  minEntrySpeed?: number;
  /** seconds this teleporter ignores the ball after it fired */
  cooldownSeconds?: number;
}

export const TELEPORTER_DEFAULTS = {
  velocityMode: 'preserve' as TeleportVelocityMode,
  exitSpeed: 6,
  speedMultiplier: 1,
  minEntrySpeed: 0.15,
  cooldownSeconds: 0.5,
} as const;

export class Teleporter implements BallObstacle<TeleporterConfig> {
  readonly id: string;
  readonly kind = 'teleporter' as const;
  enabled: boolean;
  private cooldown = 0;

  constructor(readonly config: TeleporterConfig) {
    this.id = config.id;
    this.enabled = config.enabled ?? true;
  }

  get isReady(): boolean {
    return this.enabled && this.cooldown <= 0;
  }

  get remainingCooldown(): number {
    return this.cooldown;
  }

  /** Advances the cooldown without looking at the ball. */
  tick(dt: number): void {
    if (this.cooldown > 0) this.cooldown = Math.max(0, this.cooldown - Math.max(0, dt));
  }

  /** Blocks the teleporter for a while, which stops two linked portals from ping ponging the ball. */
  suppress(seconds: number): void {
    this.cooldown = Math.max(this.cooldown, Math.max(0, seconds));
  }

  reset(): void {
    this.cooldown = 0;
  }

  update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null {
    this.tick(context.dt);
    if (!this.isReady) return null;

    const config = this.config;
    const speed = lengthVec3(ball.velocity);
    if (speed < (config.minEntrySpeed ?? TELEPORTER_DEFAULTS.minEntrySpeed)) return null;
    if (!zoneContains(config.entry, ball.position, ball.radius ?? 0)) return null;

    this.cooldown = Math.max(0, config.cooldownSeconds ?? TELEPORTER_DEFAULTS.cooldownSeconds);
    return {
      obstacleId: this.id,
      kind: this.kind,
      teleport: {
        position: cloneVec3(config.exit),
        velocity: this.exitVelocity(ball, speed),
        clearAngularVelocity: true,
      },
    };
  }

  private exitVelocity(ball: BallSample, speed: number): Vec3 {
    const config = this.config;
    const mode = config.velocityMode ?? TELEPORTER_DEFAULTS.velocityMode;
    const multiplier = clamp(config.speedMultiplier ?? TELEPORTER_DEFAULTS.speedMultiplier, 0, 4);
    const direction = config.exitDirection ? normalizeVec3(config.exitDirection) : null;
    if (mode === 'preserve' || !direction) return scaleVec3(ball.velocity, multiplier);
    const exitSpeed = mode === 'fixed' ? (config.exitSpeed ?? TELEPORTER_DEFAULTS.exitSpeed) : speed;
    return scaleVec3(direction, exitSpeed * multiplier);
  }
}

export interface TeleporterNetworkOptions {
  /** how long the teleporter at the destination stays inert after a jump lands inside it */
  exitLockSeconds?: number;
}

export const TELEPORTER_NETWORK_DEFAULTS = { exitLockSeconds: 0.6 } as const;

/** Group of teleporters of one hole, responsible for at most one jump per physics step. */
export class TeleporterNetwork {
  private readonly teleporters: Teleporter[];

  constructor(teleporters: Teleporter[] = [], private readonly options: TeleporterNetworkOptions = {}) {
    this.teleporters = [...teleporters];
  }

  add(teleporter: Teleporter): void {
    this.teleporters.push(teleporter);
  }

  get all(): readonly Teleporter[] {
    return this.teleporters;
  }

  reset(): void {
    for (const teleporter of this.teleporters) teleporter.reset();
  }

  update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null {
    let jump: ObstacleEffect | null = null;
    let source: Teleporter | null = null;
    for (const teleporter of this.teleporters) {
      if (jump) {
        teleporter.tick(context.dt);
        continue;
      }
      const effect = teleporter.update(ball, context);
      if (effect?.teleport) {
        jump = effect;
        source = teleporter;
      }
    }
    if (jump?.teleport) this.lockDestination(jump.teleport.position, source);
    return jump;
  }

  private lockDestination(exit: Vec3, source: Teleporter | null): void {
    const lock = this.options.exitLockSeconds ?? TELEPORTER_NETWORK_DEFAULTS.exitLockSeconds;
    for (const teleporter of this.teleporters) {
      if (teleporter === source) continue;
      if (zoneContains(teleporter.config.entry, exit)) teleporter.suppress(lock);
    }
  }
}
