import type { Vec3 } from '../contracts/math';
import type { BallObstacle, BallSample, ObstacleConfigBase, ObstacleEffect, ObstacleStepContext } from './types';
import { dotVec3, normalizeVec3, scaleVec3 } from './vec';
import type { ZoneShape } from './zones';
import { zoneContains } from './zones';

export interface ConveyorConfig extends ObstacleConfigBase {
  kind: 'conveyor';
  zone: ZoneShape;
  /** belt travel direction, normalized on construction */
  direction: Vec3;
  /** belt surface speed in m/s, negative values run the belt backwards */
  speed: number;
  /** how fast the ball matches the belt, 1/s, a sticky belt uses a high value */
  grip?: number;
  /** the belt never pushes the ball past this speed along the belt */
  maxCarrySpeed?: number;
}

export const CONVEYOR_DEFAULTS = { grip: 3.5 } as const;

export class Conveyor implements BallObstacle<ConveyorConfig> {
  readonly id: string;
  readonly kind = 'conveyor' as const;
  enabled: boolean;
  private readonly direction: Vec3 | null;

  constructor(readonly config: ConveyorConfig) {
    this.id = config.id;
    this.enabled = config.enabled ?? true;
    this.direction = normalizeVec3(config.direction);
  }

  /** Belt direction after normalization, or null when the configured direction is degenerate. */
  get beltDirection(): Vec3 | null {
    return this.direction;
  }

  reset(): void {}

  update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null {
    const dt = Math.max(0, context.dt);
    const direction = this.direction;
    if (!this.enabled || dt <= 0 || !direction) return null;
    if (!zoneContains(this.config.zone, ball.position, ball.radius ?? 0)) return null;

    const grip = Math.max(0, this.config.grip ?? CONVEYOR_DEFAULTS.grip);
    if (grip <= 0) return null;

    const along = dotVec3(ball.velocity, direction);
    // exponential approach keeps the belt frame rate independent and never overshoots the belt speed
    const blend = 1 - Math.exp(-grip * dt);
    let delta = (this.config.speed - along) * blend;
    const maxCarrySpeed = this.config.maxCarrySpeed;
    if (delta > 0 && maxCarrySpeed !== undefined) delta = Math.min(delta, Math.max(0, maxCarrySpeed - along));
    if (Math.abs(delta) <= 1e-6) return null;
    return { obstacleId: this.id, kind: this.kind, deltaVelocity: scaleVec3(direction, delta) };
  }
}
